    console.log("===== QUIZ AUDIT =====");
    const categories = new Set();
    const difficulties = new Set();
    const ids = new Set();
    const counts = {};
    quizQuestions.forEach(q => {
        categories.add(q.category);
        difficulties.add(q.difficulty);
        if (ids.has(q.id)) {
            console.warn("Duplicate ID:", q.id);
        }
        ids.add(q.id);
		const expectedPrefix =
			`${q.category}_${q.difficulty}_`;
		const isStandardPrefix =
			q.id.startsWith(expectedPrefix);
		const isOriginalPrefix =
			q.id.startsWith("original_");
		if (!isStandardPrefix && !isOriginalPrefix) {
			console.warn(
				"Prefix mismatch:",
				q.id,
				"expected:",
				expectedPrefix,
				"or original_"
			);
}
        const key =
            `${q.category}:${q.difficulty}`;
        counts[key] =
            (counts[key] || 0) + 1;
    });
    console.log("Categories:", [...categories]);
    console.log("Difficulties:", [...difficulties]);
    console.table(counts);
